    const n = parseInt(input[0]);
    const k = parseInt(input[1]);

    if (n === 1) {
        console.log(0);
        return;
    }

    // Precompute factorials and inverse factorials up to n
    const fact = new Array(n + 1).fill(1);
    for (let i = 1; i <= n; i++) {
        fact[i] = fact[i - 1] * i % MOD;
    }

    const inv_fact = new Array(n + 1).fill(1);
    inv_fact[n] = modInverse(fact[n], MOD);
    for (let i = n - 1; i >= 0; i--) {
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD;
    }

    let ans = 0;

    for (let m = 1; m <= n; m++) {
        const c = n - m;
        if (c < 0) continue;

        // Calculate C(n-1, m-1)
        const comb = fact[n - 1] * inv_fact[m - 1] % MOD * inv_fact[n - m] % MOD;

        // Calculate (m-1)^c mod MOD
        const power = modPow(m - 1, c, MOD);

        // Add to answer
        ans = (ans + comb * power) % MOD;
    }

    console.log(ans);
}

