const MOD = 1000000007;

function main() {
    const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
    const n = parseInt(input[0]);
    const k = parseInt(input[1]);

    if (n === 1) {
        console.log(0);
        return;
    }

    // Precompute factorials and inverse factorials up to n
    const fact = new Array(n + 1).fill(1);
    for (let i = 1; i <= n; i++) {
        fact[i] = fact[i - 1] * i % MOD;
    }

    const inv_fact = new Array(n + 1).fill(1);
    inv_fact[n] = modInv(fact[n], MOD);
    for (let i = n - 1; i >= 0; i--) {
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD;
    }

    function comb(a, b) {
        if (a < 0 || b < 0 || a < b) return 0;
        return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD;
    }

    let ans = 0;
    for (let m = 1; m <= n; m++) {
        if (m === n) continue;
        const c = comb(n - 1, m - 1);
        const term = c * fact[m] % MOD;
        term = term * fact[n - m] % MOD;
        ans = (ans + term) % MOD;
    }

    console.log(ans);
}

function modInv(a, mod) {
    let m = mod - 2;
    let res = 1;
    while (m > 0) {
        if (m & 1) res = res * a % mod;
        a = a * a % mod;
        m >>= 1;
    }
    return res;
}

main();
