        invFact[i] = invFact[i + 1] * (i + 1) % MOD;
    }

    function comb(n, k) {
        if (k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    let ans = 0;
    for (let m = 1; m <= n; m++) {
        const c = comb(n - 1, m - 1);
        const term = c * fact[m - 1] % MOD;
        term = term * fact[n - m] % MOD;
        ans = (ans + term) % MOD;
    }

    ans = (fact[n] - ans + MOD) % MOD;
    console.log(ans);
}

function modInv(a, mod) {
    let g = mod, x = 0, y = 1;
    let origMod = mod;
    while (mod !== 0) {
        let q = Math.floor(g / mod);
        [g, mod] = [mod, g % mod];
        [x, y] = [y, x - q * y];
    }
    if (x < 0) x += origMod;
    return x;
}

